#!/usr/bin/env python3
"""Render the final retrospective stress report from project-local receipts."""
import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
D = ROOT / 'tools/cde/final-stress-20261030'
OUTPUT = ROOT / 'docs/audits/final-reading-stress-2026-10-30.md'


def load(name):
    return json.loads((D / name).read_text())


def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def pct(x):
    return f'{x:.2f}'


def main():
    if OUTPUT.exists():
        raise FileExistsError(OUTPUT)
    results, refinement = load('results.json'), load('refinement.json')
    cases, inventory, baseline = load('selected-cases.json'), load('inventory.json'), load('baseline-review.json')
    generated = []
    def add(text=''):
        generated.append(text)
    add('# Final synthetic reading-estimator stress report — 2026-10-30')
    add()
    add('**Status: PARTIAL / NOT A RELEASE GATE.** The requested fresh 100-round, all-profile evaluation and individual hand grading were not completed. This report records the attempt, the completed retrospective comparisons, the resulting failures, and the remaining work. The source of every number below is the linked evidence or its recorded command output; synthetic cases are not measurements of people.')
    add()
    add('Generated by `python3 tools/cde/final_stress_report.py` (exit 0). The report generator reads existing local receipts and creates this file without overwriting an existing report. The saved detailed results were generated by `python3 tools/cde/final_stress.py analyze` and `python3 tools/cde/final_stress.py refine`, each exit 0; their saved output is in [the evidence directory](../../tools/cde/final-stress-20261030).')
    add()
    add('## 1. What was requested and what happened')
    add()
    add('- The owner requested 100 calibration rounds, every fake and disruptive profile, as much weight precision as warranted, individual manual grades, and a comprehensive report.')
    add('- A combined input was prepared for 9,946 cases, including 16 freshly generated opaque demo-persona snapshots, 24 adversarial cases, 298 corpus cases, and 9,608 synthetic cases. The duplicated earlier batch was counted once. Preparation exited 0; see [inventory](../../tools/cde/final-stress-20261030/inventory.json).')
    add('- The fresh Swift batch did not finish: its Xcode process was stopped after a file-open stall; exit 143. Its log and sampled call stack are preserved. No fresh predictions were produced for that combined batch.')
    add('- Instead, 100 different experimental blend weights were evaluated **retrospectively** on 322 previously produced Swift predictions: 24 adversarial cases and 298 corpus cases. A finer development-only piecewise-linear search was then calculated separately. The larger synthetic batches were reviewed using their previously saved production-baseline predictions, not the new blend.')
    add('- An automated arithmetic recheck covered all 32,200 rows in the 100-by-322 result file. Three extreme cases were manually inspected and are discussed below. **SKIPPED: individual human grading of all cases and rounds**; no independent reviewer graded them. Programmatic scoring is not hand grading.')
    add('- **SKIPPED: all-profile 100-round comparison**, because the fresh batch stalled and the historical synthetic receipts do not contain the experimental candidate predictions; the 16 demo snapshots likewise have no fresh estimator predictions. No production weight was changed.')
    add('- **SKIPPED: sequential stop-and-restart recalibration.** These 100 rounds are post-processing of already computed predictions, and all cases were scored after spikes; see the spike analysis. This does not reproduce the owner’s earlier stop-immediately instruction.')
    add()
    add('## 2. Scope and inventory')
    add()
    add('The 149-package score artifact is represented by the two corpus groups. Package rows include repeated content; the group-specific split was made by content digest. A package row is not an independently observed reader. Counts below are case counts, not distinct human readers.')
    add()
    add('| Source | Role assigned here | Group | Cases | Coverage in 100 trials |')
    add('|---|---|---|---:|---|')
    for row in inventory:
        coverage = 'Included' if row['group'] in ('adversarial', 'corpus') else ('Production baseline only, historical' if row['group'] == 'synthetic' else 'Snapshot only; no predictions')
        add(f"| {row['source']} | {row['split']} | {row['group']} | {row['cases']} | {coverage} |")
    add()
    add('The synthetic batches named 762943 and 762943-final have identical input, outcome and experimental CDE arrays, checked in this session; only the latter was retained in the combined case inventory. The digest-to-split construction and scenario recipes are in [the adversarial generator](../../tools/cde/adversarial_eval.py) and [the synthetic generator](../../tools/cde/synthetic_eval.py).')
    add()
    add('### Demo snapshot target')
    add()
    add('The snapshot test generates each demo library using the fixed Unix reference time 1,790,000,000. It takes the final 40 positive, closed page timings from an eligible target book as the target, and uses page timings ending no later than the first target timing as history. Each persona and book is identified by an opaque hash. All 16 personas yielded a snapshot; none was excluded. This target is **generated elapsed time over 40 visits**, not an observed person’s active reading time or necessarily the remaining 40 distinct page positions. It is not interchangeable with the other generators’ active-time target. See [snapshot test](../../AsterismaV2.0Tests/Engines/FinalStressDemoSnapshotTests.swift) and [its saved attachment manifest](../../tools/cde/final-stress-20261030/demo-attachments/manifest.json).')
    add()
    add('## 3. Experimental procedure')
    add()
    add('The existing Swift adapter reports production baseline, navigation-filtered, guarded, recent and equal-blend predictions. The present trials use `prediction = guarded_weight × guarded + (1 − guarded_weight) × recent`. The guarded and recent candidates are test-only. All predictions were obtained from saved historical Swift attachments; this run did not recompute them. The earlier batch manifests record different generator hashes; its saved candidate receipt is included as historical data, not asserted to have been produced from the current generator or adapter.')
    add()
    add('The 100 weights are exactly `i / 99` for integer i from 0 through 99. Development selection minimizes mean absolute percentage error across 250 development cases; ties choose the lowest index. The 72 comparison cases are separate saved cases but have previously been inspected: they are **not blind** and their scenario designs are not independent. The input order was shuffled with seed 947061. All trials use the same cases and fixed predictions; they are 100 weight comparisons, not 100 fresh simulations or independent experiments.')
    add()
    add('Absolute percentage error is `100 × |prediction − synthetic target| / synthetic target`. A spike is an absolute error greater than both 300 seconds and 75% of the target; this is a chosen investigation trigger, not a validated acceptance criterion. The 90th percentile uses the sorted value at Python index `round((n − 1) × 0.9)`; the median uses Python’s standard median. Precision of a weight is not precision of the estimate.')
    add()
    add('## 4. Main findings')
    add()
    add('| Model / group | Cases | Median error % | Mean error % | 90th percentile % | Worst error % | Spikes |')
    add('|---|---:|---:|---:|---:|---:|---:|')
    for label,m in [('Production baseline, development',results['baseline_development']),('Production baseline, comparison',results['baseline_evaluation']),('Best 100-grid blend, development',results['rounds'][results['selected_round']-1]['development']),('Best 100-grid blend, comparison',results['rounds'][results['selected_round']-1]['evaluation']),('Refined blend, development',refinement['development']),('Refined blend, comparison',refinement['evaluation'])]:
        add(f"| {label} | {m['cases']} | {pct(m['median_ape'])} | {pct(m['mean_ape'])} | {pct(m['p90_ape'])} | {pct(m['max_ape'])} | {m['spikes']} |")
    add()
    add(f"The grid selected round {results['selected_round']} with guarded weight {results['selected_weight']:.10f}. The separate exact-breakpoint search examined {refinement['candidate_points']} development points and found guarded weight {refinement['guarded_weight']:.10f}, recent weight {refinement['recent_weight']:.10f} (rounded to ten decimals). The unrounded floating-point values and source fingerprints are in [refinement.json](../../tools/cde/final-stress-20261030/refinement.json). This search optimizes only this particular development objective and candidate family; it does not establish a globally best formula.")
    add()
    add('The refined blend has a lower comparison median than the saved production baseline, but a higher comparison mean, a higher 90th percentile, a worse maximum, and one more spike. The comparison cases are previously exposed, so even a favorable aggregate would not prove generalization. Do not ship the experimental blend based on these data.')
    add()
    add('### Historical large-batch baseline only')
    add()
    add('| Saved batch | Cases | Median error % | Mean error % | 90th percentile % | Worst error % | Spikes |')
    add('|---|---:|---:|---:|---:|---:|---:|')
    for name,rec in baseline.items():
        m=rec['metrics']; add(f"| {name} | {m['cases']} | {pct(m['median_ape'])} | {pct(m['mean_ape'])} | {pct(m['p90_ape'])} | {pct(m['max_ape'])} | {m['spikes']} |")
    add()
    add('These two rows are recomputed from earlier baseline predictions and synthetic outcomes. They were not evaluated against the current candidate blend; they cannot fill the missing all-profile 100-round comparison. Their [baseline review receipt](../../tools/cde/final-stress-20261030/baseline-review.json) contains input and prediction fingerprints.')
    add()
    add('## 5. Manual inspection of severe examples')
    add()
    add('The three examples below were individually inspected against their stored inputs and outcomes. They are not a manual grade of the rest. Values are rounded; the complete records are in the selected-case receipt. Predictions and targets are synthetic seconds for the chosen target, not measured human times.')
    add()
    for item in sorted(cases, key=lambda x:x['absolute_percent_error'], reverse=True)[:3]:
        add(f"- **{item['id']}** ({item['source']}; position {item['position']}): target {item['actual_seconds']:.2f}, baseline {item['baseline']:.2f}, recent {item['recent']:.2f}; recent error {item['absolute_percent_error']:.2f}%. The target-book history includes long intervals mixed with shorter ones. The recent-only candidate overestimates substantially; this is compatible with interruption contamination but does not prove intent or the cause in a real session.")
    add()
    add('Another important counterexample is case `c2ee7813161de9e1`: the synthetic future is 6,279.9 seconds, the baseline and recent candidate predict about 420.0 seconds, and the guard predicts about 3,467.2 seconds. The stored recent history is very fast relative to the previous book, while the synthetic future is slower. A guard helps this case but can hurt cases where the fast pace is genuine. Neither behavior can be inferred with certainty from timing alone.')
    add()
    add('## 6. Spike and restart analysis')
    add()
    add('Every one of the 100 blends first triggers the spike rule at shuffled position 10, case `0ecd1c82b4e9a98d`. Its synthetic target is 1,198.24 seconds; both candidates predict about 2,616.76 seconds, an error of 118.38%. Since the two inputs to the blend coincide for this case, adjusting their weight cannot resolve it. All 100 calculations continued beyond that point, so they are not sequential stop-and-restart calibration rounds. A genuine stop/restart protocol would require changing the candidate or its inputs, then rerunning from position 1 and recording each attempt.')
    add()
    add('## 7. All 100 retrospective weight trials')
    add()
    add('The split is development / previously inspected comparison. Rows summarize completed post-processing trials, not fresh executions of the estimator. Weight values below are rounded; the complete precision and metrics are retained in [results.json](../../tools/cde/final-stress-20261030/results.json).')
    add()
    add('| Round | Guard weight | Dev mean % | Dev median % | Dev spikes | Comparison mean % | Comparison median % | Comparison worst % | Comparison spikes | First spike |')
    add('|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|')
    for r in results['rounds']:
        d,e=r['development'],r['evaluation']
        add(f"| {r['round']} | {r['guarded_weight']:.10f} | {pct(d['mean_ape'])} | {pct(d['median_ape'])} | {d['spikes']} | {pct(e['mean_ape'])} | {pct(e['median_ape'])} | {pct(e['max_ape'])} | {e['spikes']} | {r['first_spike_position']} |")
    add()
    add('## 8. All 322 selected-grid case records')
    add()
    add('These are the best **grid** blend results, not the separate refined blend. Case IDs are opaque. “Target” is the synthetic future value; a negative error is an underestimate. The machine-generated complete 100-round × 322-case receipt is [all-rounds.csv.gz](../../tools/cde/final-stress-20261030/all-rounds.csv.gz). The descriptions below are numerical records, not individual human verdicts.')
    add()
    add('| Position | Opaque ID | Source | Split | Target seconds | Baseline seconds | Grid prediction seconds | Signed error seconds | Absolute error % | Spike |')
    add('|---:|---|---|---|---:|---:|---:|---:|---:|---|')
    for r in cases:
        add(f"| {r['position']} | {r['id']} | {r['source']} | {r['split']} | {r['actual_seconds']:.2f} | {r['baseline']:.2f} | {r['selected_prediction']:.2f} | {r['error_seconds']:+.2f} | {r['absolute_percent_error']:.2f} | {'YES' if r['spike'] else 'no'} |")
    add()
    add('## 9. Captured attempts and verification')
    add()
    add('- `xcodebuild test -project AsterismaV2.0.xcodeproj -scheme AsterismaV2.0 -configuration Debug -destination \'platform=macOS\' -parallel-testing-enabled NO \'-only-testing:AsterismaV2.0Tests/FinalStressDemoSnapshotTests\' -resultBundlePath tools/cde/final-stress-20261030/demo.xcresult` — exit 0; one snapshot test passed, capturing 16 and excluding 0. See [demo log](../../tools/cde/final-stress-20261030/demo.log).')
    add('- `xcrun xcresulttool export attachments --path tools/cde/final-stress-20261030/demo.xcresult --output-path tools/cde/final-stress-20261030/demo-attachments` — exit 0; one attachment exported.')
    add('- `python3 tools/cde/final_stress.py prepare` — exit 0; 9,946 combined cases prepared. Existing request file was created only for the next attempt and removed afterward.')
    add('- `xcodebuild test -project AsterismaV2.0.xcodeproj -scheme AsterismaV2.0 -configuration Debug -destination \'platform=macOS\' -parallel-testing-enabled NO \'-only-testing:AsterismaV2.0Tests/AdversarialEvaluationTests\' -resultBundlePath tools/cde/final-stress-20261030/batch.xcresult` — interrupted, exit 143; one small adapter test passed, optional batch never completed. The sampled stack showed a wait in the request-file open call. See [batch log](../../tools/cde/final-stress-20261030/batch.log) and [sample](../../tools/cde/final-stress-20261030/batch.sample.txt). The cause of the OS-level wait was not established.')
    add('- `python3 tools/cde/final_stress.py reuse` — exit 0; 322 historical candidate records reused. `python3 tools/cde/final_stress.py baseline-review` — exit 0; historical baseline summaries created. `python3 tools/cde/final_stress.py analyze` and `python3 tools/cde/final_stress.py refine` — exit 0 on final analysis; earlier intermediate outputs were preserved separately after the script gained the baseline-review action.')
    add('- `python3 -m py_compile tools/cde/final_stress.py` — exit 0. An independent Python arithmetic loop checked 100 distinct weights, 322 unique case IDs, 32,200 percentage-error and spike calculations, the grid winner and the refined development mean; it exited 0. It did not independently verify the original Swift predictions, synthetic assumptions, or grade every case by hand.')
    add('- `python3 -m unittest discover -s tools/cde -p \'test_adversarial_eval.py\' -v` — exit 0; three tests passed. These are harness invariants, not evidence of human accuracy.')
    add('- `./scripts/verify-sentinel-surface.sh` — exit 0. `python3 scripts/comprehension-bench.py --validate-only` — exit 0. `./scripts/census.sh --unit-only` — exit 0; Xcode summary reported 495 passed, 0 failed, 9 skipped, 504 total. The skipped tests are not passes. See [census log](../../tools/cde/final-stress-20261030/census.log).')
    add('- The optional adversarial batch test returns without running a batch when its request file is absent. The successful unit census therefore does not establish that the failed 9,946-case batch succeeded.')
    add()
    add('### Byte-level receipts')
    add()
    add('The following SHA-256 values are calculated from the current files when this report is generated. They identify evidence bytes; they do not validate the underlying assumptions.')
    add()
    for path in ['tools/cde/final_stress.py','tools/cde/final_stress_report.py','tools/cde/final-stress-20261030/app-input.json','tools/cde/final-stress-20261030/truth.json','tools/cde/final-stress-20261030/retrospective-predictions.json','tools/cde/final-stress-20261030/results.json','tools/cde/final-stress-20261030/refinement.json','tools/cde/final-stress-20261030/selected-cases.json','tools/cde/final-stress-20261030/all-rounds.csv.gz','tools/cde/final-stress-20261030/baseline-review.json']:
        add(f'- [{Path(path).name}](../../{path}) — SHA-256 `{sha(ROOT/path)}`.')
    add()
    add('## 10. Interpretation and remaining risks')
    add()
    add('1. Synthetic future outcomes and book response effects were invented by generators. A small error means agreement with these assumptions, not demonstrated accuracy for real readers.')
    add('2. The reader adapter injects already-closed page records. Real sessions can have an open current page; PDF polling, EPUB mapping, background closure, and SQLite summary reload were not exercised. The previous audit identified these as potential differences; the present run does not resolve them.')
    add('3. The histories used for selection and comparison were generated and inspected in earlier work. The apparent comparison set is neither fresh nor independently blinded, and repeated fitting may overfit it.')
    add('4. The first saved adversarial batch used a different recorded generator digest from the later batches. Do not assume identical generator versions or data-generating distributions. Compare manifests and saved source receipts before treating differences as causal.')
    add('5. A grid and an exact search across a single two-candidate blend do not explore every formula or establish the “best possible” weights. More decimal places do not fix missing information or biased synthetic targets.')
    add('6. **SKIPPED: individual grading of every case and round**, **SKIPPED: fresh all-profile predictions**, and **SKIPPED: real-reader validation**. A reviewer and a resolved file-access issue are needed before making those claims.')
    add("7. No production estimator source, release, commit or push was changed by this experiment. The working tree already contained unrelated and earlier-session modifications; the report does not claim a clean checkout. The test host launched the app; no inspection was made of the user's persisted library.")
    add()
    add('## 11. Suggested next action')
    add()
    add('Resolve the test-host file-open stall without using personal data; rerun the full combined batch with strict ID matching; then define a fresh, never-inspected evaluation set and a genuine stop-at-spike/restart procedure. Have a separate reviewer grade cases against a written rubric. Compare against production and test actual session and SQLite persistence paths before considering any production weight change.')
    OUTPUT.write_text('\n'.join(generated)+'\n')
    print('wrote', OUTPUT.relative_to(ROOT), 'lines', len(generated), 'sha256', sha(OUTPUT))


if __name__ == '__main__':
    main()
